-- =============================================================================
-- MediCore HMS — Triggers and appointment status audit (Review 3)
-- =============================================================================
-- Part 1 is byte-for-byte the migration
--   backend/prisma/migrations/20261011130000_dbms_triggers_audit/migration.sql
-- (audit table DDL generated by Prisma from the AppointmentStatusAudit model).
-- Part 2 tests when each trigger does and does not fire, and rollback.
-- Run on a disposable database after 01, 02, 06 and 07.
-- =============================================================================

-- ---------------------------- Part 1: definitions ----------------------------
-- DBMS Review 3 — triggers and appointment status audit history.
--
-- The audit table is modelled in schema.prisma (AppointmentStatusAudit) so
-- Prisma Migrate sees no drift; its DDL below is exactly what
-- `prisma migrate diff` generates for that model. Trigger functions and
-- triggers are not represented in schema.prisma and are ignored by Prisma's
-- diff, so they live only in this migration.

-- CreateTable
CREATE TABLE "appointment_status_audit" (
    "id" BIGSERIAL NOT NULL,
    "appointmentId" UUID NOT NULL,
    "oldStatus" "AppointmentStatus" NOT NULL,
    "newStatus" "AppointmentStatus" NOT NULL,
    "changedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "changedBy" VARCHAR(63) NOT NULL,

    CONSTRAINT "appointment_status_audit_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "appointment_status_audit_appointmentId_changedAt_idx" ON "appointment_status_audit"("appointmentId", "changedAt");

-- AddForeignKey
-- ON DELETE CASCADE: appointments are never deleted by the application
-- (patients/doctors use RESTRICT), but the Jest fixtures delete their own test
-- appointments; CASCADE keeps that cleanup working. Trade-off: deleting an
-- appointment also deletes its audit history.
ALTER TABLE "appointment_status_audit" ADD CONSTRAINT "appointment_status_audit_appointmentId_fkey" FOREIGN KEY ("appointmentId") REFERENCES "appointments"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- -----------------------------------------------------------------------------
-- Trigger A: keep queries.respondedAt consistent with queries.adminResponse.
--
-- BEFORE INSERT OR UPDATE, row level. Rules:
--   * A blank/whitespace-only response is stored as NULL.
--   * No response  -> respondedAt is NULL (a timestamp without a response is
--                     meaningless).
--   * INSERT with a response and no respondedAt -> respondedAt = now().
--     An explicitly supplied respondedAt is kept (seed/demo data).
--   * UPDATE that changes the response (set or edited) -> respondedAt = now().
--   * UPDATE that leaves the response unchanged -> respondedAt untouched.
-- It never changes "status" or "updatedAt": status transitions stay with the
-- caller (API or sp_respond_to_query) and updatedAt stays application-managed.
-- Only NEW is modified (BEFORE trigger), so it cannot recurse.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION "trg_fn_queries_responded_at"()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  NEW."adminResponse" := NULLIF(btrim(NEW."adminResponse"), '');

  IF NEW."adminResponse" IS NULL THEN
    NEW."respondedAt" := NULL;
  ELSIF TG_OP = 'INSERT' THEN
    NEW."respondedAt" := COALESCE(NEW."respondedAt", now());
  ELSIF NEW."adminResponse" IS DISTINCT FROM OLD."adminResponse" THEN
    NEW."respondedAt" := now();
  END IF;

  RETURN NEW;
END;
$$;

COMMENT ON FUNCTION "trg_fn_queries_responded_at"() IS
  'BEFORE INSERT/UPDATE on queries: blank response -> NULL; no response -> respondedAt NULL; new or changed response -> respondedAt = now().';

CREATE TRIGGER "trg_queries_responded_at"
BEFORE INSERT OR UPDATE OF "adminResponse", "respondedAt" ON "queries"
FOR EACH ROW
EXECUTE FUNCTION "trg_fn_queries_responded_at"();

-- -----------------------------------------------------------------------------
-- Trigger B: audit appointment status changes.
--
-- AFTER UPDATE OF "status", row level, and only WHEN the value actually
-- changed (IS DISTINCT FROM), so re-saving the same status writes nothing.
-- Not fired on INSERT: the booking path stays untouched; a new appointment's
-- initial status is already on the appointment row itself.
-- Records old/new status, now() (transaction time) and session_user — the
-- database login role. With the shared application connection that is the app
-- role, NOT the person logged in to Express.
-- The audit row is written in the same transaction as the status change, so a
-- ROLLBACK removes both.
-- SECURITY DEFINER lets the audit row be written even when the role changing
-- the status has no INSERT privilege on the audit table (so the audit table
-- can be read-only for everyone else).
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION "trg_fn_appointments_status_audit"()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  INSERT INTO "appointment_status_audit" ("appointmentId", "oldStatus", "newStatus", "changedAt", "changedBy")
  VALUES (NEW."id", OLD."status", NEW."status", now(), session_user);
  RETURN NULL; -- AFTER trigger: return value is ignored
END;
$$;

COMMENT ON FUNCTION "trg_fn_appointments_status_audit"() IS
  'AFTER UPDATE OF status on appointments: inserts one appointment_status_audit row per real status change.';

REVOKE EXECUTE ON FUNCTION "trg_fn_appointments_status_audit"() FROM PUBLIC;

CREATE TRIGGER "trg_appointments_status_audit"
AFTER UPDATE OF "status" ON "appointments"
FOR EACH ROW
WHEN (OLD."status" IS DISTINCT FROM NEW."status")
EXECUTE FUNCTION "trg_fn_appointments_status_audit"();

-- =============================================================================
-- DEMONSTRATION AND TESTS (not part of the migration)
-- Requires 02_dml.sql demo data and 07 (sp_cancel_appointment) for T-B5.
-- Every block runs inside BEGIN ... ROLLBACK, so demo data is unchanged.
-- =============================================================================

-- T-0  Installed triggers.
SELECT event_object_table AS table_name, trigger_name, action_timing, event_manipulation,
       action_condition
FROM information_schema.triggers
WHERE trigger_schema = 'public'
ORDER BY table_name, trigger_name, event_manipulation;

-- ================================ Trigger A: queries.respondedAt ============
BEGIN;
-- T-A1  INSERT with a response but no respondedAt -> respondedAt filled.
-- T-A2  INSERT with a blank response and a respondedAt -> both NULL.
-- T-A3  INSERT with no response -> respondedAt NULL.
INSERT INTO "queries" ("id", "patientId", "subject", "message", "adminResponse", "respondedAt", "updatedAt") VALUES
  ('00000000-0000-4000-a000-0000000007a1', '00000000-0000-4000-a000-000000000201', 'T-A1', 'm', 'Answered on insert', NULL, now()),
  ('00000000-0000-4000-a000-0000000007a2', '00000000-0000-4000-a000-000000000201', 'T-A2', 'm', '   ', TIMESTAMPTZ '2026-01-01 00:00+00', now()),
  ('00000000-0000-4000-a000-0000000007a3', '00000000-0000-4000-a000-000000000201', 'T-A3', 'm', NULL, NULL, now());
SELECT "subject", "adminResponse", "respondedAt" = now() AS responded_now, "respondedAt" IS NULL AS responded_null
FROM "queries" WHERE "subject" LIKE 'T-A%' ORDER BY "subject";

-- T-A4  Response set on an OPEN query (702) -> respondedAt = now().
UPDATE "queries" SET "adminResponse" = 'Weekday slots only.' WHERE "id" = '00000000-0000-4000-a000-000000000702';
-- T-A5  Response edited on resolved query 701 (was responded 2026-09-12) -> now().
UPDATE "queries" SET "adminResponse" = 'Edited answer.' WHERE "id" = '00000000-0000-4000-a000-000000000701';
-- T-A6  Response re-saved unchanged on closed query 704 -> respondedAt kept.
UPDATE "queries" SET "adminResponse" = "adminResponse" WHERE "id" = '00000000-0000-4000-a000-000000000704';
-- T-A7  Response cleared on 0007a1 -> respondedAt NULL.
UPDATE "queries" SET "adminResponse" = NULL WHERE "id" = '00000000-0000-4000-a000-0000000007a1';
-- T-A8  Status-only change on 703 -> trigger not fired (UPDATE OF column list), respondedAt untouched.
UPDATE "queries" SET "status" = 'RESOLVED' WHERE "id" = '00000000-0000-4000-a000-000000000703';

SELECT "subject", "status", "adminResponse", "respondedAt",
       "respondedAt" = now() AS responded_now
FROM "queries"
WHERE "id" IN ('00000000-0000-4000-a000-000000000702', '00000000-0000-4000-a000-000000000701',
               '00000000-0000-4000-a000-000000000704', '00000000-0000-4000-a000-0000000007a1',
               '00000000-0000-4000-a000-000000000703')
ORDER BY "subject";
ROLLBACK;

-- ================================ Trigger B: appointment status audit =======
BEGIN;
-- T-B1  Real status change BOOKED -> CONFIRMED on 510: one audit row.
UPDATE "appointments" SET "status" = 'CONFIRMED', "updatedAt" = now()
WHERE "id" = '00000000-0000-4000-a000-000000000510';
-- T-B2  Same status written again: WHEN clause suppresses the trigger.
UPDATE "appointments" SET "status" = 'CONFIRMED', "updatedAt" = now()
WHERE "id" = '00000000-0000-4000-a000-000000000510';
-- T-B3  Non-status column change: UPDATE OF "status" does not fire.
UPDATE "appointments" SET "notes" = 'Bring ECG reports.', "updatedAt" = now()
WHERE "id" = '00000000-0000-4000-a000-000000000510';
-- T-B4  Multi-row update (two BOOKED appointments of Dr Mehta / Dr Kapoor): one row each.
UPDATE "appointments" SET "status" = 'CONFIRMED', "updatedAt" = now()
WHERE "id" IN ('00000000-0000-4000-a000-000000000511', '00000000-0000-4000-a000-000000000513');
-- T-B5  Change made through the stored procedure is audited too.
CALL sp_cancel_appointment('00000000-0000-4000-a000-000000000510', 'CANCELLED_BY_PATIENT',
                           'Audit demo', TIMESTAMPTZ '2026-10-10 09:00+00');

SELECT right(au."appointmentId"::text, 3) AS appt, au."oldStatus", au."newStatus",
       au."changedBy", au."changedAt" = now() AS changed_in_this_txn
FROM "appointment_status_audit" au
ORDER BY au."id";
-- Expected: 510 BOOKED->CONFIRMED, 511 BOOKED->CONFIRMED, 513 BOOKED->CONFIRMED,
--           510 CONFIRMED->CANCELLED_BY_PATIENT  (4 rows; none for T-B2/T-B3)
ROLLBACK;

-- T-B6  Rollback semantics: the audit row disappears with the status change.
BEGIN;
UPDATE "appointments" SET "status" = 'CONFIRMED', "updatedAt" = now()
WHERE "id" = '00000000-0000-4000-a000-000000000512';
SELECT COUNT(*) AS audit_rows_inside_txn FROM "appointment_status_audit";
ROLLBACK;
SELECT COUNT(*) AS audit_rows_after_rollback FROM "appointment_status_audit";

-- T-B7  Failed statement: a status change that violates a constraint writes no audit row.
DO $$
BEGIN
  UPDATE "appointments" SET "status" = 'CONFIRMED', "endTime" = '09:00', "updatedAt" = now()
  WHERE "id" = '00000000-0000-4000-a000-000000000512';   -- endTime before startTime 14:00
  RAISE EXCEPTION 'FAIL: invalid update accepted';
EXCEPTION WHEN check_violation THEN
  RAISE NOTICE 'PASS invalid update rejected, audit rows now: %',
    (SELECT COUNT(*) FROM "appointment_status_audit");
END $$;

-- Final state: demo data unchanged.
SELECT (SELECT "status" FROM "appointments" WHERE "id" = '00000000-0000-4000-a000-000000000510') AS appt_510,
       (SELECT "respondedAt" FROM "queries" WHERE "id" = '00000000-0000-4000-a000-000000000701') AS query_701_responded_at,
       (SELECT COUNT(*) FROM "appointment_status_audit") AS audit_rows;
